#[sqlx::test(migrations = "../../migrations")]
async fn new_model_overrides_require_native_support_without_blocking_defaults_or_receipt_replay(
    pool: PgPool,
) {
    let (store, actor, profile) = setup(&pool).await;
    let mut active = update(&profile);
    active.model_settings = SavedModelSettingsV1 {
        schema_version: SchemaV1,
        use_default_model_settings: false,
        saved_model: Some("fixture-model".into()),
        saved_reasoning_effort: Some("fixture-effort".into()),
        saved_fast_mode: false,
    };
    assert!(matches!(
        store.update_codex_profile(&actor, "activate", profile.id, &active, verified).await,
        Err(StoreError::Domain(domain::DomainError::CapabilityUnavailable(_)))
    ));
    let ticket = prepare(&store, &actor, &profile, "support").await;
    let outcome = available(&profile, ticket.started_at);
    store.complete_codex_probe(ticket, outcome).await.unwrap();
    for (key, model, effort, fast) in [
        ("unknown-model", Some("missing"), Some("fixture-effort"), false),
        ("unknown-effort", None, Some("missing"), false),
        ("unknown-fast", None, None, true),
    ] {
        let mut invalid = active.clone();
        invalid.model_settings.saved_model = model.map(str::to_owned);
        invalid.model_settings.saved_reasoning_effort = effort.map(str::to_owned);
        invalid.model_settings.saved_fast_mode = fast;
        assert!(matches!(
            store.update_codex_profile(&actor, key, profile.id, &invalid, verified).await,
            Err(StoreError::Domain(domain::DomainError::CapabilityUnavailable(_)))
        ));
    }
    let unchanged = store.codex_profile(&actor, profile.id).await.unwrap();
    assert_eq!(unchanged.revision, profile.revision);
    assert_eq!(unchanged.model_settings, profile.model_settings);
    let dormant = store.update_codex_profile(
        &actor, "keep-dormant", profile.id, &update(&profile), verified,
    ).await.unwrap().resource;
    active.expected_revision = dormant.revision;
    assert!(matches!(
        store.update_codex_profile(&actor, "activate", profile.id, &active, verified).await,
        Err(StoreError::Domain(domain::DomainError::CapabilityUnavailable(_)))
    ));
    let ticket = prepare(&store, &actor, &dormant, "refreshed-support").await;
    let outcome = available(&dormant, ticket.started_at);
    store.complete_codex_probe(ticket, outcome).await.unwrap();
    let saved = store.update_codex_profile(
        &actor, "activate", profile.id, &active, verified,
    ).await.unwrap();
    assert!(!saved.replayed);
    assert_eq!(saved.resource.model_settings, active.model_settings);

    let failed = prepare(&store, &actor, &saved.resource, "later-failure").await;
    store.complete_codex_probe(
        failed,
        CodexProbeOutcomeV1::Unavailable { reason: CodexProbeFailureV1::NativeUnavailable },
    ).await.unwrap();
    let replay = store.update_codex_profile(
        &actor, "activate", profile.id, &active,
        |_| async { Err(StoreError::Invalid("replay_must_not_reverify")) },
    ).await.unwrap();
    assert!(replay.replayed);
    assert_eq!(serde_json::to_value(&replay.resource).unwrap(), serde_json::to_value(&saved.resource).unwrap());
    let mut fresh_command = active.clone();
    fresh_command.expected_revision = saved.resource.revision;
    assert!(matches!(
        store.update_codex_profile(&actor, "new-activation", profile.id, &fresh_command, verified).await,
        Err(StoreError::Domain(domain::DomainError::CapabilityUnavailable(_)))
    ));
    fresh_command.model_settings = profile.model_settings;
    let recovered = store.update_codex_profile(
        &actor, "restore-defaults", profile.id, &fresh_command, verified,
    ).await.unwrap();
    assert!(recovered.resource.model_settings.use_default_model_settings);
    assert_eq!(recovered.resource.model_settings, fresh_command.model_settings);
}

#[sqlx::test(migrations = "../../migrations")]
async fn expired_catalog_blocks_new_activation_without_rewriting_historical_observation(pool: PgPool) {
    let (store, actor, profile) = setup(&pool).await;
    // A historical observation fixture, not an edited live native result or clock.
    let observed = Utc::now() - chrono::Duration::seconds(120);
    let outcome = json!({"schema_version":1,"result":available(&profile, observed)});
    let id: uuid::Uuid = sqlx::query_scalar("INSERT INTO app.codex_profile_observations(profile_id,profile_revision,observed_at,valid_until,outcome) VALUES($1,$2,$3,$4,$5) RETURNING id")
        .bind(profile.id.as_uuid()).bind(profile.revision.get() as i64)
        .bind(observed).bind(observed + chrono::Duration::seconds(60)).bind(&outcome)
        .fetch_one(&pool).await.unwrap();
    let mut active = update(&profile);
    active.model_settings.use_default_model_settings = false;
    active.model_settings.saved_model = Some("fixture-model".into());
    active.model_settings.saved_reasoning_effort = None;
    active.model_settings.saved_fast_mode = false;
    assert!(matches!(
        store.update_codex_profile(&actor, "expired", profile.id, &active, verified).await,
        Err(StoreError::Domain(domain::DomainError::CapabilityUnavailable(_)))
    ));
    let retained: serde_json::Value =
        sqlx::query_scalar("SELECT outcome FROM app.codex_profile_observations WHERE id=$1")
            .bind(id).fetch_one(&pool).await.unwrap();
    assert_eq!(retained, outcome);
    assert_eq!(store.codex_profile(&actor, profile.id).await.unwrap().revision, profile.revision);
}

#[sqlx::test(migrations = "../../migrations")]
async fn supported_native_fast_only_setting_uses_the_observed_model(pool: PgPool) {
    let (store, actor, profile) = setup(&pool).await;
    let ticket = prepare(&store, &actor, &profile, "native-tier").await;
    let mut outcome = available(&profile, ticket.started_at);
    if let CodexProbeOutcomeV1::Available { models, .. } = &mut outcome {
        models[0].service_tiers.push(CodexServiceTierV1 {
            id: "priority".into(), name: "Native priority".into(), description: String::new(),
        });
    }
    store.complete_codex_probe(ticket, outcome).await.unwrap();
    let mut active = update(&profile);
    active.model_settings.use_default_model_settings = false;
    active.model_settings.saved_model = None;
    active.model_settings.saved_reasoning_effort = None;
    active.model_settings.saved_fast_mode = true;
    let saved = store.update_codex_profile(&actor, "fast-only", profile.id, &active, verified)
        .await.unwrap().resource;
    assert_eq!(saved.model_settings, active.model_settings);
}

#[sqlx::test(migrations = "../../migrations")]
async fn raw_http_cannot_activate_unobserved_model_settings(pool: PgPool) {
    let home = tempfile::tempdir().unwrap();
    let (f, cookie) = configured(pool.clone(), home.path(), std::env::current_exe().unwrap()).await;
    let profile = local_profile(&f, &cookie).await;
    let id = profile["id"].as_str().unwrap();
    let path = format!("/api/v2/settings/codex/{id}");
    let mut settings = profile["model_settings"].clone();
    settings["use_default_model_settings"] = json!(false);
    settings["saved_model"] = json!("unobserved-model");
    let request = json!({
        "schema_version":1, "expected_revision":profile["revision"], "model_settings":settings
    });
    let denied = command(&f, &cookie, "unobserved", "PATCH", &path, request).await;
    assert_eq!(denied.status, StatusCode::SERVICE_UNAVAILABLE, "{}", denied.body);
    let current = support::call(&f, "GET", &path, Value::Null, Some(&cookie)).await;
    assert_eq!(current.body, profile);
    let observations: i64 = sqlx::query_scalar("SELECT count(*) FROM app.codex_profile_observations")
        .fetch_one(&pool).await.unwrap();
    assert_eq!(observations, 0, "saving must not execute a probe");
}
